Here's a complete single-file version that loads `kb.txt`, builds a context-aware (trigram by default) language model, then uses your `Kernel` (`Reality`, `Dark`, `Desire`) to modify probabilities before sampling the next token.

```python
from __future__ import annotations

import math
import re
from collections import Counter, defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Sequence, Tuple

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

EPS = 1e-12


# ============================================================
# Utility
# ============================================================

def norm(p: torch.Tensor) -> torch.Tensor:
    return p / p.sum().clamp_min(EPS)


def ent(p: torch.Tensor) -> torch.Tensor:
    q = p.clamp_min(EPS)
    return -(q * q.log()).sum()


def cos(a: torch.Tensor, b: torch.Tensor) -> float:
    n = min(len(a), len(b))

    if n == 0:
        return 0.0

    a = a[:n].double()
    b = b[:n].double()

    return float(
        F.cosine_similarity(
            a.unsqueeze(0),
            b.unsqueeze(0),
        ).item()
    )


# ============================================================
# World Model
# ============================================================

@dataclass
class World:
    p: torch.Tensor
    chosen: str = ""
    rho: float = 1.0
    sig: torch.Tensor = field(
        default_factory=lambda: torch.zeros(
            1,
            dtype=torch.float64,
        )
    )


@dataclass
class Sig:
    chosen: str
    rho: float
    desire: float
    dark: float
    entropy: float
    vec: torch.Tensor

    def sim(self, other: "Sig") -> float:
        return cos(self.vec, other.vec)


# ============================================================
# Desire Layer
# ============================================================

class Desire(nn.Module):
    def __init__(
        self,
        n: int,
        strength: float = 0.15,
    ):
        super().__init__()

        self.strength = nn.Parameter(
            torch.tensor(
                strength,
                dtype=torch.float64,
            )
        )

        self.prior = nn.Parameter(
            torch.zeros(
                n,
                dtype=torch.float64,
            )
        )

    def forward(
        self,
        p: torch.Tensor,
    ) -> Tuple[torch.Tensor, float]:

        n = len(p)

        prior = (
            self.prior[:n]
            if n <= len(self.prior)
            else F.pad(
                self.prior,
                (0, n - len(self.prior)),
            )
        )

        prior = norm(
            F.softmax(
                prior.float(),
                dim=0,
            ).double()
        )

        s = float(
            self.strength.clamp(
                0.0,
                0.5,
            )
        )

        q = norm(
            (1.0 - s) * p +
            s * prior
        )

        w = float(
            F.cosine_similarity(
                p.unsqueeze(0),
                prior.unsqueeze(0),
            )
            .clamp(0.0, 1.0)
            .item()
        )

        return q, s * w


# ============================================================
# Dark Layer
# ============================================================

class Dark(nn.Module):
    def __init__(
        self,
        strength: float = 0.30,
        tail_q: float = 0.40,
    ):
        super().__init__()

        self.strength = nn.Parameter(
            torch.tensor(
                strength,
                dtype=torch.float64,
            )
        )

        self.tail_q = nn.Parameter(
            torch.tensor(
                tail_q,
                dtype=torch.float64,
            )
        )

    def forward(
        self,
        p: torch.Tensor,
        rho: float,
    ) -> torch.Tensor:

        if len(p) == 0:
            return p

        s = float(
            self.strength.clamp(
                0.0,
                1.0,
            )
        )

        tq = float(
            self.tail_q.clamp(
                0.05,
                0.95,
            )
        )

        sp, idx = torch.sort(
            p,
            descending=True,
        )

        cum = torch.cumsum(
            sp,
            dim=0,
        )

        mask = torch.zeros_like(p)

        mask[idx[cum > tq]] = 1.0

        return norm(
            p *
            (
                1.0 +
                (1.0 - rho) *
                s *
                mask
            )
        )


# ============================================================
# Reality Layer
# ============================================================

class Reality(nn.Module):
    def __init__(
        self,
        ew: float = 0.20,
    ):
        super().__init__()

        self.ew = nn.Parameter(
            torch.tensor(
                ew,
                dtype=torch.float64,
            )
        )

    def forward(
        self,
        locked: int,
        missing: int,
        p: torch.Tensor,
    ) -> float:

        total = locked + missing

        base = (
            0.0
            if total == 0
            else (
                1.0
                if missing == 0
                else locked / total
            )
        )

        h = float(ent(p))

        hmax = math.log(
            max(1, len(p))
        )

        return float(
            base *
            (
                1.0 -
                float(
                    self.ew.clamp(
                        0.0,
                        1.0,
                    )
                ) *
                (
                    h /
                    max(EPS, hmax)
                )
            )
        )


# ============================================================
# Kernel
# ============================================================

class Kernel(nn.Module):
    def __init__(
        self,
        vocab: Sequence[str],
    ):
        super().__init__()

        self.vocab = list(vocab)

        self.desire = Desire(
            len(self.vocab)
        )

        self.dark = Dark()
        self.reality = Reality()

        self.sigs: List[Sig] = []

    def make_sig(
        self,
        chosen,
        p,
        rho,
        dw,
        dm,
    ):

        vec = torch.tensor(
            [
                float(p.max()),
                float(ent(p)),
                rho,
                dw,
                dm,
            ],
            dtype=torch.float64,
        )

        return Sig(
            chosen,
            rho,
            dw,
            dm,
            float(ent(p)),
            vec,
        )

    def step(
        self,
        p: torch.Tensor,
        locked: int = 0,
        missing: int = 0,
    ) -> World:

        p = norm(
            p.double()
        )

        rho = self.reality(
            locked,
            missing,
            p,
        )

        p1 = self.dark(
            p,
            rho,
        )

        p2, dw = self.desire(
            p1
        )

        idx = int(
            torch.multinomial(
                p2,
                1,
            ).item()
        )

        chosen = self.vocab[idx]

        dm = float(
            (p2 - p1)
            .clamp_min(0)
            .sum()
        )

        sig = self.make_sig(
            chosen,
            p2,
            rho,
            dw,
            dm,
        )

        self.sigs.append(sig)

        return World(
            p=p2,
            chosen=chosen,
            rho=rho,
            sig=sig.vec,
        )

    def report(self):

        if not self.sigs:
            return {"n": 0}

        return {
            "n": len(self.sigs),
            "rho_mean": float(
                np.mean(
                    [s.rho for s in self.sigs]
                )
            ),
            "entropy_mean": float(
                np.mean(
                    [s.entropy for s in self.sigs]
                )
            ),
        }


# ============================================================
# Dataset
# ============================================================

def tokenize(text: str):
    text = text.lower()
    return re.findall(
        r"\w+|[^\w\s]",
        text,
    )


def load_dataset(
    path: str,
    context_size: int = 3,
):

    text = Path(path).read_text(
        encoding="utf-8"
    )

    tokens = tokenize(text)

    vocab = sorted(
        set(tokens)
    )

    transitions = defaultdict(
        Counter
    )

    for i in range(
        len(tokens) - context_size
    ):
        context = tuple(
            tokens[
                i:i + context_size
            ]
        )

        nxt = tokens[
            i + context_size
        ]

        transitions[
            context
        ][nxt] += 1

    return (
        tokens,
        vocab,
        transitions,
        context_size,
    )


# ============================================================
# N-Gram Backoff
# ============================================================

def next_distribution(
    context,
    vocab,
    transitions,
):

    vocab_index = {
        w: i
        for i, w in enumerate(vocab)
    }

    for size in range(
        len(context),
        0,
        -1,
    ):
        sub = tuple(
            context[-size:]
        )

        counts = transitions.get(sub)

        if counts:
            p = torch.zeros(
                len(vocab),
                dtype=torch.float64,
            )

            for word, count in counts.items():
                p[
                    vocab_index[word]
                ] = float(count)

            return norm(p)

    return torch.ones(
        len(vocab),
        dtype=torch.float64,
    ) / len(vocab)


# ============================================================
# Text Generation
# ============================================================

def generate_text(
    kernel: Kernel,
    vocab,
    transitions,
    seed_words,
    context_size,
    length=200,
):

    words = list(seed_words)

    for i in range(length):

        context = tuple(
            words[-context_size:]
        )

        p = next_distribution(
            context,
            vocab,
            transitions,
        )

        world = kernel.step(
            p,
            locked=i + 1,
            missing=max(
                0,
                length - i,
            ),
        )

        words.append(
            world.chosen
        )

    return " ".join(words)


# ============================================================
# Main
# ============================================================

def main():

    torch.manual_seed(42)

    (
        tokens,
        vocab,
        transitions,
        context_size,
    ) = load_dataset(
        "kb.txt",
        context_size=3,
    )

    kernel = Kernel(vocab)

    seed_words = tokens[
        :context_size
    ]

    generated = generate_text(
        kernel,
        vocab,
        transitions,
        seed_words,
        context_size,
        length=250,
    )

    print("\n=== GENERATED TEXT ===\n")
    print(generated)

    print("\n=== REPORT ===\n")
    print(kernel.report())


if __name__ == "__main__":
    main()
```

Improvements over your version:

- Uses a **3-token context window** instead of a single word.
- Supports **backoff** when an exact context isn't found.
- Better tokenization (keeps punctuation as tokens).
- Uses your `Reality`, `Dark`, and `Desire` layers during generation.
- Loads directly from `kb.txt`.
- Produces substantially more coherent text than the original one-word transition model.

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Callable, Dict, List, Optional, Sequence, Tuple
from collections import defaultdict, Counter
from pathlib import Path
import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F

EPS = 1e-12


def norm(p: torch.Tensor) -> torch.Tensor:
    return p / p.sum().clamp_min(EPS)


def ent(p: torch.Tensor) -> torch.Tensor:
    q = p.clamp_min(EPS)
    return -(q * q.log()).sum()


def cos(a: torch.Tensor, b: torch.Tensor) -> float:
    n = min(len(a), len(b))
    if n == 0:
        return 0.0
    a = a[:n].double()
    b = b[:n].double()
    return float(F.cosine_similarity(a.unsqueeze(0), b.unsqueeze(0)).item())


@dataclass
class World:
    p: torch.Tensor
    chosen: str = ""
    rho: float = 1.0
    sig: torch.Tensor = field(default_factory=lambda: torch.zeros(1, dtype=torch.float64))


@dataclass
class Frame:
    W: List[World]
    R: Callable[[World], List[World]]


@dataclass
class Model:
    F: Frame
    V: Callable[[World, str], bool]


@dataclass
class Sig:
    chosen: str
    rho: float
    desire: float
    dark: float
    entropy: float
    vec: torch.Tensor

    def sim(self, other: "Sig") -> float:
        return cos(self.vec, other.vec)


class Desire(nn.Module):
    def __init__(self, n: int, strength: float = 0.15):
        super().__init__()
        self.strength = nn.Parameter(torch.tensor(float(strength), dtype=torch.float64))
        self.prior = nn.Parameter(torch.zeros(n, dtype=torch.float64))

    def forward(self, p: torch.Tensor) -> Tuple[torch.Tensor, float]:
        n = len(p)
        prior = self.prior[:n] if n <= len(self.prior) else F.pad(self.prior, (0, n - len(self.prior)))
        prior = norm(F.softmax(prior.float(), dim=0).double())
        s = float(self.strength.clamp(0.0, 0.5))
        q = norm((1.0 - s) * p + s * prior)
        w = float(F.cosine_similarity(p.unsqueeze(0), prior.unsqueeze(0)).clamp(0.0, 1.0).item())
        return q, s * w


class Dark(nn.Module):
    def __init__(self, strength: float = 0.30, tail_q: float = 0.40):
        super().__init__()
        self.strength = nn.Parameter(torch.tensor(float(strength), dtype=torch.float64))
        self.tail_q = nn.Parameter(torch.tensor(float(tail_q), dtype=torch.float64))

    def forward(self, p: torch.Tensor, rho: float) -> torch.Tensor:
        if len(p) == 0:
            return p
        s = float(self.strength.clamp(0.0, 1.0))
        tq = float(self.tail_q.clamp(0.05, 0.95))
        sp, idx = torch.sort(p, descending=True)
        cum = torch.cumsum(sp, dim=0)
        mask = torch.zeros_like(p)
        mask[idx[cum > tq]] = 1.0
        return norm(p * (1.0 + (1.0 - rho) * s * mask))


class Reality(nn.Module):
    def __init__(self, ew: float = 0.20):
        super().__init__()
        self.ew = nn.Parameter(torch.tensor(float(ew), dtype=torch.float64))

    def forward(self, locked: int, missing: int, p: torch.Tensor) -> float:
        total = locked + missing
        base = 0.0 if total == 0 else (1.0 if missing == 0 else locked / total)
        h = float(ent(p.clamp_min(EPS)))
        hmax = math.log(max(1, len(p)))
        return float(base * (1.0 - float(self.ew.clamp(0.0, 1.0)) * (h / max(EPS, hmax))))


class Kernel(nn.Module):
    def __init__(self, vocab: Sequence[str]):
        super().__init__()
        self.vocab = list(vocab)
        self.desire = Desire(len(self.vocab))
        self.dark = Dark()
        self.reality = Reality()
        self.sigs: List[Sig] = []
        self.hist: Dict[str, int] = {w: 0 for w in self.vocab}

    def sig(self, chosen: str, p: torch.Tensor, rho: float, dw: float, dm: float) -> Sig:
        v = torch.tensor([float(p.max()), float(ent(p)), rho, dw, dm], dtype=torch.float64)
        return Sig(chosen, rho, dw, dm, float(ent(p)), v)

    def step(self, p: torch.Tensor, locked: int = 0, missing: int = 0) -> World:
        p = norm(p.double())
        rho = self.reality(locked, missing, p)
        p1 = self.dark(p, rho)
        p2, dw = self.desire(p1)
        idx = int(torch.multinomial(p2, 1).item()) if len(p2) else 0
        chosen = self.vocab[idx] if idx < len(self.vocab) else ""
        dm = float((p2 - p1).clamp_min(0).sum())
        s = self.sig(chosen, p2, rho, dw, dm)
        self.sigs.append(s)
        self.hist[chosen] = self.hist.get(chosen, 0) + 1
        return World(p=p2, chosen=chosen, rho=rho, sig=s.vec)

    def truth(self, w: World, prop: str) -> bool:
        if prop == "simplex":
            return abs(float(w.p.sum()) - 1.0) < 1e-5 and bool((w.p >= 0).all())
        if prop == "dream":
            return w.rho < 0.5
        if prop == "awake":
            return w.rho >= 0.5
        if prop == "familiar":
            return self.familiarity(5) > 0.8
        if prop == "locked":
            return w.chosen in self.hist
        return False

    def familiarity(self, n: int = 5) -> float:
        xs = self.sigs[-n:]
        if len(xs) < 2:
            return 0.0
        s = 0.0
        c = 0
        for i in range(len(xs)):
            for j in range(i + 1, len(xs)):
                s += xs[i].sim(xs[j])
                c += 1
        return s / c if c else 0.0

    def report(self) -> Dict[str, float]:
        if not self.sigs:
            return {"n": 0.0}
        return {
            "n": float(len(self.sigs)),
            "rho_mean": float(np.mean([x.rho for x in self.sigs])),
            "entropy_mean": float(np.mean([x.entropy for x in self.sigs])),
            "dark_mean": float(np.mean([x.dark for x in self.sigs])),
            "desire_mean": float(np.mean([x.desire for x in self.sigs])),
            "familiarity_5": float(self.familiarity(5)),
        }


def build_kernel(vocab: Sequence[str]) -> Kernel:
    return Kernel(vocab)

def load_dataset(path: str):
    text = Path(path).read_text(encoding="utf-8")

    tokens = text.split()

    vocab = sorted(set(tokens))
    word_to_id = {w: i for i, w in enumerate(vocab)}

    transitions = defaultdict(Counter)

    for a, b in zip(tokens[:-1], tokens[1:]):
        transitions[a][b] += 1

    return tokens, vocab, word_to_id, transitions
def next_distribution(
    current_word: str,
    vocab: list[str],
    transitions,
) -> torch.Tensor:

    counts = transitions.get(current_word)

    if not counts:
        return torch.ones(len(vocab), dtype=torch.float64)

    p = torch.zeros(len(vocab), dtype=torch.float64)

    vocab_index = {w: i for i, w in enumerate(vocab)}

    for word, count in counts.items():
        p[vocab_index[word]] = float(count)

    return norm(p)


def generate_text(
    kernel: Kernel,
    vocab: list[str],
    transitions,
    start_word: str,
    length: int = 50,
):
    words = [start_word]
    current = start_word

    for _ in range(length):
        p = next_distribution(current, vocab, transitions)

        world = kernel.step(p)

        current = world.chosen

        if not current:
            break

        words.append(current)

    return " ".join(words)

def main():
    torch.manual_seed(42)

    _, vocab, _, transitions = load_dataset("kb.txt")

    kernel = build_kernel(vocab)

    start_word = vocab[0]

    text = generate_text(
        kernel,
        vocab,
        transitions,
        start_word=start_word,
        length=100,
    )

    print(text)



if __name__ == "__main__":
    main()

