        return World(p=p2, chosen=chosen, rho=rho, sig=s.vec)

    def truth(self, w: World, prop: str) -> bool:
        if prop == "simplex":
            return abs(float(w.p.sum()) - 1.0) < 1e-5 and bool((w.p >= 0).all())
        if prop == "dream":
            return w.rho < 0.5
        if prop == "awake":
            return w.rho >= 0.5
        if prop == "familiar":
            return self.familiarity(5) > 0.8
        if prop == "locked":
            return w.chosen in self.hist
        return False

    def familiarity(self, n: int = 5) -> float:
        xs = self.sigs[-n:]
        if len(xs) < 2:
            return 0.0
        s = 0.0
        c = 0
        for i in range(len(xs)):
            for j in range(i + 1, len(xs)):
                s += xs[i].sim(xs[j])
                c += 1
        return s / c if c else 0.0

    def report(self) -> Dict[str, float]:
        if not self.sigs:
            return {"n": 0.0}
        return {
            "n": float(len(self.sigs)),
            "rho_mean": float(np.mean([x.rho for x in self.sigs])),
            "entropy_mean": float(np.mean([x.entropy for x in self.sigs])),
            "dark_mean": float(np.mean([x.dark for x in self.sigs])),
            "desire_mean": float(np.mean([x.desire for x in self.sigs])),
            "familiarity_5": float(self.familiarity(5)),
        }


