- publishes via MQTT,
- stores the count in flash memory so it survives reboots,
- or uses the sensor interrupt pin instead of polling.

"""
block_shell_exe.py - Binary patcher to block shell execution inside x86/x64 EXEs

REQUIREMENTS:
    pip install lief

USAGE:
    python block_shell_exe.py input.exe output_patched.exe
"""

import sys
import os
import lief


BLOCKED_APIS = {
    'CreateProcessA', 'CreateProcessW', 'WinExec',
    'ShellExecuteA', 'ShellExecuteW',
    'ShellExecuteExA', 'ShellExecuteExW',
    'system', '_wsystem'
}

API_DLLS = {'kernel32.dll', 'kernel32', 'shell32.dll', 'shell32', 'msvcrt.dll', 'msvcrt'}


class ShellBlockPatcher:
    def __init__(self, input_path: str, output_path: str):
        self.input_path = input_path
        self.output_path = output_path
        self.binary = None
        self.patches_applied = []

    def load_binary(self) -> bool:
        try:
            self.binary = lief.parse(self.input_path)

            if self.binary is None:
                print(f"[-] Error: Failed to parse PE file: {self.input_path}")
                return False

            machine = self.binary.header.machine
            MACHINE_TYPES = lief.PE.Header.MACHINE_TYPES

            if machine == MACHINE_TYPES.I386:
                arch_str = "32-bit (x86)"
            elif machine == MACHINE_TYPES.AMD64:
                arch_str = "64-bit (x64)"
            else:
                arch_str = f"Unknown ({machine})"

            print(f"[+] Loaded PE file: {self.input_path}")
            print(f"    Architecture: {arch_str}")
            return True
        except Exception as e:
            print(f"[-] Error loading binary: {e}")
            return False

    def find_blocked_imports(self) -> list:
        found_imports = []

        if not self.binary:
            return found_imports

        print("[*] Scanning for blocked APIs in imports...")

        try:
            for library in self.binary.imports:
                dll_name = library.name

                if any(dll.lower() in dll_name.lower() for dll in API_DLLS):
                    print(f"    [+] Found DLL: {dll_name}")

                    for entry in library.entries:
                        func_name = entry.name

                        if func_name in BLOCKED_APIS:
                            found_imports.append({'dll': dll_name, 'function': func_name})
                            print(f"    [!] BLOCKED API FOUND: {func_name}")
        except Exception as e:
            print(f"[-] Error scanning imports: {e}")
            return []

        return found_imports

    def patch_import(self, api_info: dict) -> bool:
        try:
            if not self.binary:
                return False

            dll_name = api_info['dll']
            func_name = api_info['function']

            for library in self.binary.imports:
                if dll_name.lower() in library.name.lower():
                    if library.remove_entry(func_name):
                        print(f"    [+] Removed {func_name} from import table")
                        self.patches_applied.append({'type': 'import_removal', 'dll': dll_name, 'function': func_name})
                        return True
                    else:
                        print(f"    [-] Failed to remove {func_name}")
                        return False

            print(f"    [-] Could not find {dll_name} in imports")
            return False
        except Exception as e:
            print(f"    [-] Error patching import: {e}")
            return False

    def save_patched_binary(self) -> bool:
        try:
            if not self.binary:
                return False

            # FIX: Use binary.write() directly instead of Builder
            self.binary.write(self.output_path)

            file_size = os.path.getsize(self.output_path)
            print(f"[+] Saved patched binary: {self.output_path}")
            print(f"    File size: {file_size} bytes")
            return True
        except Exception as e:
            print(f"[-] Error saving patched binary: {e}")
            return False

    def verify_patch(self) -> bool:
        try:
            patched_binary = lief.parse(self.output_path)
            found_blocked = []

            for library in patched_binary.imports:
                dll_name = library.name
                if any(dll.lower() in dll_name.lower() for dll in API_DLLS):
                    for entry in library.entries:
                        if entry.name in BLOCKED_APIS:
                            found_blocked.append(entry.name)

            if found_blocked:
                print(f"[-] Warning: Still found blocked APIs: {found_blocked}")
                return False
            else:
                print("[+] Verified: No blocked APIs found in imports")
                return True
        except Exception as e:
            print(f"[-] Error verifying patch: {e}")
            return False

    def run(self) -> bool:
        print("=" * 60)
        print("SHELL EXECUTION BLOCKER - Binary Patcher")
        print("=" * 60)
        print(f"Input:  {self.input_path}")
        print(f"Output: {self.output_path}")
        print()

        if not self.load_binary():
            return False
        print()

        blocked_imports = self.find_blocked_imports()

        if not blocked_imports:
            print("[+] No blocked APIs found in imports")
            print("[*] EXE may not use shell functions")
            import shutil
            shutil.copy2(self.input_path, self.output_path)
            print(f"[+] Copied original to: {self.output_path}")
            return True
        print()

        print(f"[*] Patching {len(blocked_imports)} blocked API(s)...")
        for api in blocked_imports:
            if self.patch_import(api):
                print(f"    ✓ Patched: {api['function']}")
            else:
                print(f"    ✗ Failed: {api['function']}")
        print()

        if not self.save_patched_binary():
            return False
        print()

        print("[*] Verifying patch...")
        self.verify_patch()
        print()

        print("=" * 60)
        print("PATCH SUMMARY")
        print("=" * 60)
        print(f"Patches applied: {len(self.patches_applied)}")
        for patch in self.patches_applied:
            if patch['type'] == 'import_removal':
                print(f"  - Removed: {patch['function']} from {patch['dll']}")
        print()

        return True


def main():
    if len(sys.argv) != 3:
        print("Usage: python block_shell_exe.py <input.exe> <output_patched.exe>")
        print("\nExample: python block_shell_exe.py myapp.exe myapp_patched.exe")
        print("\nThis will patch the EXE to block:")
        for api in sorted(BLOCKED_APIS):
            print(f"  - {api}")
        sys.exit(1)

    input_exe = sys.argv[1]
    output_exe = sys.argv[2]

    if not os.path.exists(input_exe):
        print(f"[-] Error: Input file not found: {input_exe}")
        sys.exit(1)

    patcher = ShellBlockPatcher(input_exe, output_exe)
    success = patcher.run()
    sys.exit(0 if success else 1)


if __name__ == "__main__":
    main()
