    n = len(s)
    step = max(1, n // max_pts)
    idx = list(range(0, n, step))
    if idx and idx[-1] != n - 1:
        idx.append(n - 1)
    xs = [0.0] + [round(float(s[i]), 4) for i in idx]
    ys = [0.0] + [round((i + 1) / n, 4) for i in idx]
    return xs, ys


def slope_schedule(mean_gap: float, mode: str, steps: int):
    if mode == "piecewise":
        bands = [(0.25, 2.0), (0.5, 1.0), (0.75, 0.5), (0.9, 0.25)]
        return [(f"p{int(p*100)}", max(1, int(mean_gap * mult))) for p, mult in bands]
    if mode == "staircase":
        return [(f"step{i+1}", max(1, int(mean_gap * (2.0 / (i + 1))))) for i in range(steps)]
    return [(f"adapt{i+1}", max(1, int(mean_gap * (1.5 ** (-i))))) for i in range(steps)]


def extrapolate_gap(mu_ref: float, diff_ref: int, diff_new: int) -> float:
    return mu_ref * (2.0 ** (diff_new - diff_ref))


