__device__ uint64_t dsha(uint64_t nonce) {
    uint8_t buf[64] = {0};

    for (int i = 0; i < 8; i++)
        buf[i] = (nonce >> (56 - i*8)) & 0xff;

    buf[8] = 0x80;
    buf[63] = 0x08;

    uint32_t s[8] = {
