async function autoDeleteCookies(pageUrl, detectedServices) {
  try {
    const url = new URL(pageUrl);

    const cookies = await chrome.cookies.getAll({
      domain: url.hostname
    });

    const cookieNamesToDelete = new Set();

    for (const service of Object.values(detectedServices)) {
