### What this adds

- **Bigrams + Trigrams** (better local coherence)
- **Word clusters** (words appearing in similar contexts are grouped)
- **Fallback to cluster words** when a transition is missing
- **Memory retrieval scoring**
- **Less repetitive output**

Example:

```python
from collections import defaultdict, Counter
import numpy as np


class TrigramEngine:
    def __init__(self):
        self.bigrams = defaultdict(Counter)
        self.trigrams = defaultdict(Counter)

        self.word_cluster = {}
        self.cluster_words = defaultdict(set)

        self.vocab = set()

    def train(self, texts):
        contexts = defaultdict(Counter)

        for text in texts:
            tokens = text.lower().split()

            self.vocab.update(tokens)

            for i in range(len(tokens)-1):
                self.bigrams[tokens[i]][tokens[i+1]] += 1

            for i in range(len(tokens)-2):
                self.trigrams[
                    (tokens[i], tokens[i+1])
                ][tokens[i+2]] += 1

            for i in range(1, len(tokens)-1):
                word = tokens[i]
                left = tokens[i-1]
                right = tokens[i+1]

                contexts[word][left] += 1
                contexts[word][right] += 1

        self._build_clusters(contexts)

    def _build_clusters(self, contexts):
        """
        Extremely lightweight clustering.
        Words with similar top context words
        end up in same cluster.
        """

        cluster_id = 0

        for word, ctx in contexts.items():
            signature = tuple(
                sorted(
                    [w for w, _ in ctx.most_common(3)]
                )
            )

            if signature not in self.word_cluster:
                self.word_cluster[signature] = cluster_id
                cluster_id += 1

            cid = self.word_cluster[signature]
            self.cluster_words[cid].add(word)

    def random_word(self):
        return np.random.choice(list(self.vocab))

    def _sample(self, counter, temperature=0.8):

        words = list(counter.keys())

        counts = np.array(
            list(counter.values()),
            dtype=np.float32
        )

        counts = np.sqrt(counts)

        logits = np.log(counts + 1e-9)
        logits /= temperature

        probs = np.exp(logits - np.max(logits))
        probs /= probs.sum()

        return np.random.choice(words, p=probs)

    def next_word(self, w1, w2, temperature=0.8):

        tri_key = (w1, w2)

        if tri_key in self.trigrams:
            return self._sample(
                self.trigrams[tri_key],
                temperature
            )

        if w2 in self.bigrams:
            return self._sample(
                self.bigrams[w2],
                temperature
            )

        return self.cluster_fallback(w2)

    def cluster_fallback(self, word):

        for cid, words in self.cluster_words.items():

            if word in words:

                candidates = list(words)

                if candidates:
                    return np.random.choice(candidates)

        return self.random_word()
