            for k in sorted_keys
        ]

    def _remap_vocab(self):
        if not self.latent_curve:
            return set()

        self.global_shift = (
            self.global_shift + 1
        ) % len(self.latent_curve)

        return self.latent_curve[self.global_shift]

    def remap_token(self, token, current_bucket):
        if (
            token in self.remap_memory
            and self.remap_memory[token]
        ):
            return self._sample(
                self.remap_memory[token],
                temperature=0.7
            )

        if token in current_bucket:
            return token

        return random.choice(list(current_bucket))

    def cluster_fallback(self, word):
        if not self.latent_curve:
            return (
                random.choice(self.vocab)
                if self.vocab
                else None
            )

        idx = self.global_shift % len(self.latent_curve)

        words = self.latent_curve[idx]

        if words:
            return random.choice(list(words))

        return (
            random.choice(self.vocab)
            if self.vocab
            else None
        )

    # ------------------------------------------------------------------
    # Tokenization
    # ------------------------------------------------------------------

    def tokenize(self, text):
        return re.findall(
            r"\w+|[^\w\s]",
            text.lower(),
            flags=re.UNICODE
        )

    def detokenize(self, tokens):
        out = []

        for tok in tokens:
            if not out:
                out.append(tok)

            elif re.fullmatch(r"[^\w\s]", tok):
                out[-1] += tok

            else:
                out.append(" " + tok)

        return "".join(out).strip()

    # ------------------------------------------------------------------
    # Training
    # ------------------------------------------------------------------

    def train(self, texts):
        contexts = defaultdict(Counter)
        all_tokens = []

        for text in texts:
            tokens = self.tokenize(text)

            if not tokens:
                continue

            analysis = self.sentence_analysis(tokens)

            self.dataset_analysis.append({
                "tokens": tokens,
                "analysis": analysis
            })

            all_tokens.extend(tokens)

            for i in range(len(tokens) - 1):
                w1 = tokens[i]
                w2 = tokens[i + 1]

                self.bigrams[w1][w2] += 1

                self.lru[w1] = True
                self.lru.move_to_end(w1)

            for i in range(len(tokens) - 2):
                self.trigrams[
                    (tokens[i], tokens[i + 1])
                ][tokens[i + 2]] += 1

            for i in range(1, len(tokens) - 1):
                contexts[tokens[i]][tokens[i - 1]] += 1
                contexts[tokens[i]][tokens[i + 1]] += 1

        self.vocab = list(set(all_tokens))

        self._build_clusters(contexts)

        while len(self.bigrams) > self.capacity:
            oldest, _ = self.lru.popitem(last=False)

            if oldest in self.bigrams:
                del self.bigrams[oldest]

    # ------------------------------------------------------------------
    # Sampling
    # ------------------------------------------------------------------

    def _sample(self, counter, temperature=0.8):
        if not counter:
            return None

        words = list(counter.keys())

        counts = np.sqrt(
            np.array(
                list(counter.values()),
                dtype=np.float64
            )
        )

        logits = (
            np.log(counts + 1e-12)
            / max(float(temperature), 1e-6)
        )

        logits -= np.max(logits)

        probs = np.exp(logits)
        probs /= np.sum(probs)

        return np.random.choice(
            words,
            p=probs
        )

    def adaptive_temperature(
        self,
        base_temperature,
        generation_analysis
    ):
        entropy = generation_analysis["entropy_seed"]

        modifier = (
            np.tanh(entropy / 1000.0)
            * 0.5
        )

        return float(
            max(
                0.2,
                min(
                    2.0,
                    base_temperature + modifier
                )
            )
        )

    def next_word(
        self,
        w1,
        w2,
        temp
    ):
        if (w1, w2) in self.trigrams:
            nxt = self._sample(
                self.trigrams[(w1, w2)],
                temp
            )

            if nxt:
                return nxt

        if w2 in self.bigrams:
            nxt = self._sample(
                self.bigrams[w2],
                temp
            )

            if nxt:
                return nxt

        return self.cluster_fallback(w2)

    # ------------------------------------------------------------------
    # Generation
    # ------------------------------------------------------------------

    def generate_response(
        self,
        prompt,
        length=30,
        temperature=0.8
    ):
        prompt_vec = self.analyze_prompt(prompt)

        generation_analysis = (
            self.build_generation_analysis(
                prompt_vec
            )
        )

        temperature = self.adaptive_temperature(
            temperature,
            generation_analysis
        )

        current_bucket = self._remap_vocab()

        if not current_bucket:
            current_bucket = set(self.vocab)

        prompt_tokens = self.tokenize(prompt)

        remapped_seeds = []

        for token in prompt_tokens:
            mapped = self.remap_token(
                token,
                current_bucket
            )

            remapped_seeds.append(mapped)

            self.remap_memory[token][mapped] += 1

        if not remapped_seeds:
            remapped_seeds = [
                random.choice(
                    list(current_bucket)
                )
            ]

        self.seed_history.append({
            "shift": self.global_shift,
            "seeds": remapped_seeds,
            "analysis": prompt_vec
        })

        historical = random.choice(
            self.seed_history
        )["seeds"]

        w1 = historical[0]
        w2 = (
            historical[1]
            if len(historical) > 1
            else w1
        )

        output = [w1, w2]

        for _ in range(length):
            nxt = self.next_word(
                w1,
                w2,
                temperature
            )

            if not nxt:
                break

            output.append(nxt)

            w1, w2 = w2, nxt

        return self.detokenize(output)

    # ------------------------------------------------------------------
    # Analysis inspection
    # ------------------------------------------------------------------

    def dataset_stats(self):
        if not self.dataset_analysis:
            return None

        matrix = np.vstack([
            item["analysis"]
            for item in self.dataset_analysis
        ])

        return {
            "mean": matrix.mean(axis=0),
            "std": matrix.std(axis=0),
            "count": len(matrix)
        }


