import numpy as np
import re
from collections import Counter, defaultdict


class InfluenceSpaceMarkov:
    def __init__(self, beta=1.5, random_state=None):
        self.beta = beta
        self.rng = np.random.default_rng(random_state)

    def fit(self, text):
        sentences = re.split(r'(?<=[.!?])\s+', text.strip())
        self._sentence_words = [
            s.lower().split()
            for s in sentences
            if s.strip()
        ]

        all_words = [w for sent in self._sentence_words for w in sent]
        self.vocab = sorted(set(all_words))
        self.word_to_idx = {w: i for i, w in enumerate(self.vocab)}

        n = len(self.vocab)
        counts = np.zeros((n, n), dtype=float)

        for sent in self._sentence_words:
            for a, b in zip(sent[:-1], sent[1:]):
                i = self.word_to_idx[a]
                j = self.word_to_idx[b]
                counts[i, j] += 1.0

        log_counts = np.log1p(counts)
        influence = np.exp(self.beta * log_counts)
        influence[counts == 0] = 0.0

        self.Y = influence

        row_sums = influence.sum(axis=1, keepdims=True)
        self.P = np.divide(
            influence,
            row_sums,
            out=np.zeros_like(influence),
            where=row_sums != 0
        )

        return self

    def influence(self, word, min_strength=1.0):
        i = self.word_to_idx[word]
        row = self.Y[i]
        ranking = np.argsort(row)[::-1]
        return [
            (self.vocab[j], float(row[j]))
            for j in ranking
            if row[j] >= min_strength
        ]

    def next_word(self, current):
        i = self.word_to_idx[current]
        probs = self.P[i]
        if probs.sum() == 0:
            return self.rng.choice(self.vocab)
        probs = probs / probs.sum()
        return self.rng.choice(self.vocab, p=probs)

    def build_ngram_choice(self, n=2):
        if n < 1:
            raise ValueError("n must be >= 1")

        context_counts = defaultdict(Counter)

        for sent in self._sentence_words:
            if len(sent) < n:
                continue
            for k in range(len(sent) - n + 1):
                context = tuple(sent[k:k + n - 1]) if n > 1 else ()
                nxt = sent[k + n - 1]
                context_counts[context][nxt] += 1

        choice = {}
        for context, candidates in context_counts.items():
            best_count = max(candidates.values())
            winners = sorted(
                w for w, c in candidates.items() if c == best_count
            )
            choice[context] = winners[0]

        self.ngram_n = n
        self.ngram_choice = choice
        self.ngram_candidates = dict(context_counts)
        return choice

    def trace_sequence(self, start_context, max_len=50):
        if not hasattr(self, "ngram_choice"):
